#${cid}-root .url { font:500 25px 'IBM Plex Mono',monospace; margin:0; }
${s.id === '05-ask' ? `#${cid}-root h1,#${cid}-root .line.accent,#${cid}-root .note,#${cid}-root .kicker{color:#0F0F0F}` : ''}
